#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <time.h>

#define FRAMES 40
#define STALL_FRAME 20
#define FRAME_MS 20
#define STALL_MS 500

static double now_s(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

static void sleep_ms(long ms)
{
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int main(void)
{
    const double dt = FRAME_MS / 1000.0; /* one sim step is 20 ms: 50 Hz */
    double t0 = now_s();
    double acc = 0.0;
    int total = 0;

    for (int frame = 1; frame <= FRAMES; frame++) {
        sleep_ms(frame == STALL_FRAME ? STALL_MS : FRAME_MS);

        double t1 = now_s();
        acc += t1 - t0;
        t0 = t1;

        int steps = 0;
        while (acc >= dt) {
            acc -= dt;
            steps++;
            total++;
        }

        printf("frame %2d  steps %2d  total %3d\n", frame, steps, total);
    }

    return 0;
}
